mapper.select:
SELECT * FROM rec_online_assessment

    deleted = 0

        AND candidate_id = #{params.candidateId}


        AND candidate_name LIKE CONCAT('%', #{params.candidateName}, '%')


        AND candidate_email LIKE CONCAT('%', #{params.candidateEmail}, '%')


        AND status = #{params.status}


        AND type = #{params.type}


        AND create_time >= #{params.startDate}


        AND create_time <= CONCAT(#{params.endDate}, ' 23:59:59')


ORDER BY create_time DESC
